/* HEXA BATTLEGROUNDS setup — PART 5 OF 20. Run parts in order. Safe to re-run. */ create or replace function captain_use_item(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; it items; v_qty int; v_dest text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; select * into it from items where id = p_item; if it.id is null then raise exception 'BAD_ITEM'; end if; if it.kind = 'weapon' then raise exception 'USE_ATTACK'; end if; select qty into v_qty from inventory where team_id = t.id and item_id = p_item; if coalesce(v_qty, 0) < 1 then raise exception 'NO_ITEM'; end if; if t.state = 'recovery' and p_item <> 'medkit' then raise exception 'IN_RECOVERY'; end if; case p_item when 'medkit' then if t.state = 'recovery' then raise exception 'IN_RECOVERY'; end if; if t.hp >= _cfg(t.event_id, 'hp_max') then raise exception 'HP_FULL'; end if; perform _apply(t.id, 'medkit', 0, 0, (it.params ->> 'heal')::int, 0, null, 'Used a med kit'); when 'shield' then update teams set shield = least(_cfg(t.event_id, 'shield_max'), shield + (it.params ->> 'shield')::int) where id = t.id; when 'scanner' then update teams set scan_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'jammer' then update teams set jammed_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'beacon' then if t.beacon then raise exception 'ALREADY_ACTIVE'; end if; update teams set beacon = true where id = t.id; when 'extract' then if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; v_dest := _nearest_safe(coalesce(t.travel_to, t.location_id), least(5, a.zone_stage + 1)); update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop'); update teams set state = 'idle', location_id = v_dest, travel_to = null, travel_from = null, travel_arrive_at = null, dropped = true, visit_missions = 0 where id = t.id; else raise exception 'BAD_ITEM'; end case; perform _add_item(t.id, p_item, -1); insert into ledger(arena_id, team_id, kind, ref, reason, actor) values (t.arena_id, t.id, 'item_used', null, p_item, 'captain'); perform _ping_team(t.id, 'item'); return jsonb_build_object('used', p_item, 'location', v_dest); end $$; create or replace function captain_buy(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; l locations; it items; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into l from locations where id = t.location_id; if t.state <> 'idle' or not (l.tags && array['market', 'social']) then raise exception 'NO_MARKET_HERE'; end if; select * into it from items where id = p_item; if it.id is null or it.price <= 0 then raise exception 'BAD_ITEM'; end if; if 'social' = any(l.tags) and not ('market' = any(l.tags)) and it.kind not in ('intel', 'stealth', 'airdrop') then raise exception 'NOT_SOLD_HERE'; end if; if t.coins < it.price then raise exception 'NOT_ENOUGH_COINS'; end if; perform _apply(t.id, 'purchase', 0, -it.price, 0, 0, null, 'Bought ' || it.name); perform _add_item(t.id, p_item, 1); perform _ping_team(t.id, 'item'); return jsonb_build_object('bought', p_item); end $$; create or replace function captain_attack(p_token text, p_target uuid, p_weapon text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; d teams; a arenas; it items; v_tpl text; v_bid uuid; v_secs int; v_qty int; v_al alliances; begin p := _auth_captain(p_token); perform 1 from teams where id in (p.team_id, p_target) order by id for update; select * into t from teams where id = p.team_id; select * into d from teams where id = p_target; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_BATTLES_NOW'; end if; if d.id is null or d.arena_id <> t.arena_id or d.id = t.id or not d.ready then raise exception 'BAD_TARGET'; end if; if t.state <> 'idle' or d.state <> 'idle' then raise exception 'TARGET_UNAVAILABLE'; end if; if t.location_id is distinct from d.location_id then raise exception 'NOT_IN_RANGE'; end if; if t.attack_cooldown_until > now() then raise exception 'COOLDOWN'; end if; if d.protected_until > now() then raise exception 'TARGET_PROTECTED'; end if; if exists (select 1 from battles where status = 'active' and (attacker_id in (t.id, d.id) or defender_id in (t.id, d.id))) then raise exception 'ALREADY_IN_BATTLE'; end if; if exists (select 1 from mission_instances where team_id in (t.id, d.id) and status = 'active' and sync_round_id is not null) then raise exception 'TARGET_UNAVAILABLE'; end if; select * into it from items where id = p_weapon and kind = 'weapon'; if it.id is null then raise exception 'BAD_WEAPON'; end if; select qty into v_qty from inventory where team_id = t.id and item_id = p_weapon; if coalesce(v_qty, 0) < 1 then raise exception 'NO_ITEM'; end if; if (it.params ->> 'consumable')::boolean then perform _add_item(t.id, p_weapon, -1); end if; select * into v_al from alliances where status = 'active' and ((team_a = t.id and team_b = d.id) or (team_a = d.id and team_b = t.id)) for update; if v_al.id is not null then update alliances set status = 'betrayed' where id = v_al.id; perform _apply(t.id, 'betrayal', 0, 0, 0, -20, v_al.id::text, 'Betrayed an ally'); update arenas set threat = threat + 1 where id = a.id; perform _feed(a.id, 'alliance.betrayed', jsonb_build_object('by', t.number, 'victim', d.number)); end if; v_tpl := _pick_template(t.id, 'battle', array[it.params ->> 'tag']); if v_tpl is null then raise exception 'NO_TEMPLATE'; end if; v_secs := (it.params ->> 'seconds')::int; insert into battles(arena_id, attacker_id, defender_id, weapon, template_id, location_id, damage, deadline) values (a.id, t.id, d.id, p_weapon, v_tpl, t.location_id, (it.params ->> 'damage')::int, now() + _secs(v_secs)) returning id into v_bid; perform _start_instance(t.id, v_tpl, t.location_id, v_bid, null, null, now() + _secs(v_secs)); perform _start_instance(d.id, v_tpl, t.location_id, v_bid, null, null, now() + _secs(v_secs)); update mission_instances set deadline = deadline + _secs(v_secs) where team_id in (t.id, d.id) and status = 'active' and kind <> 'battle'; perform _feed(a.id, 'battle.started', jsonb_build_object('attacker', t.number, 'defender', d.number, 'weapon', p_weapon, 'location', t.location_id)); perform _ping_team(d.id, 'battle'); perform _ping_arena(a.id, 'battle'); return jsonb_build_object('battle', v_bid); end $$; create or replace function captain_claim_airdrop(p_token text, p_airdrop uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; ad airdrops; v_id uuid; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into ad from airdrops where id = p_airdrop; if ad.id is null or ad.arena_id <> t.arena_id or ad.status <> 'open' then raise exception 'AIRDROP_GONE'; end if; if t.location_id is distinct from ad.location_id or t.state <> 'idle' then raise exception 'NOT_IN_RANGE'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle') then raise exception 'MISSION_ACTIVE'; end if; v_id := _start_instance(t.id, ad.template_id, ad.location_id, null, ad.id, null, least(ad.expires_at, now() + interval '150 seconds')); perform _feed(t.arena_id, 'airdrop.contested', jsonb_build_object('team', t.number, 'location', ad.location_id)); perform _ping_arena(t.arena_id, 'airdrop'); return jsonb_build_object('instance', v_id); end $$; create or replace function captain_chat(p_token text, p_to_team int, p_body text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; d teams; v_recent int; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id; select * into d from teams where arena_id = t.arena_id and number = p_to_team and ready; if d.id is null or d.id = t.id then raise exception 'BAD_TARGET'; end if; if p_body is null or char_length(trim(p_body)) = 0 or char_length(p_body) > 280 then raise exception 'BAD_MESSAGE'; end if; if exists (select 1 from chat_blocks where team_id = d.id and blocked_team = t.id) then raise exception 'BLOCKED'; end if; select count(*) into v_recent from chat_messages where from_team = t.id and at > now() - interval '30 seconds'; if v_recent >= _cfg(t.event_id, 'chat_limit') then raise exception 'SLOW_DOWN'; end if; insert into chat_messages(arena_id, from_team, to_team, body) values (t.arena_id, t.id, d.id, trim(p_body)); perform _ping_team(d.id, 'chat'); perform _ping_team(t.id, 'chat'); return jsonb_build_object('sent', true); end $$; create or replace function captain_block(p_token text, p_team int, p_block boolean) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; d teams; begin p := _auth_player(p_token); if p.role <> 'captain' then raise exception 'NOT_CAPTAIN'; end if; select * into t from teams where id = p.team_id; select * into d from teams where arena_id = t.arena_id and number = p_team; if d.id is null then raise exception 'BAD_TARGET'; end if; if p_block then insert into chat_blocks values (t.id, d.id) on conflict do nothing; else delete from chat_blocks where team_id = t.id and blocked_team = d.id; end if; perform _ping_team(t.id, 'chat'); return jsonb_build_object('blocked', p_block); end $$; create or replace function captain_report(p_token text, p_message bigint) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; begin p := _auth_player(p_token); if p.role <> 'captain' then raise exception 'NOT_CAPTAIN'; end if; update chat_messages set reported = true where id = p_message and to_team = p.team_id; return jsonb_build_object('reported', found); end $$; create or replace function captain_alliance(p_token text, p_action text, p_team int default null, p_alliance uuid default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; d teams; al alliances; v_cost int; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id; v_cost := _cfg(t.event_id, 'alliance_cost'); if p_action = 'propose' then select * into d from teams where arena_id = t.arena_id and number = p_team and ready; if d.id is null or d.id = t.id then raise exception 'BAD_TARGET'; end if; if t.trust < 0 then raise exception 'TRUST_TOO_LOW'; end if; if exists (select 1 from alliances where status in ('proposed', 'active') and ((team_a = t.id and team_b = d.id) or (team_a = d.id and team_b = t.id))) then raise exception 'ALREADY_PENDING'; end if; insert into alliances(arena_id, team_a, team_b, proposed_by, expires_at) values (t.arena_id, t.id, d.id, t.id, now() + make_interval(mins => _cfg(t.event_id, 'alliance_minutes'))); perform _ping_team(d.id, 'alliance'); elsif p_action in ('accept', 'decline') then select * into al from alliances where id = p_alliance and status = 'proposed' and team_b = t.id for update; if al.id is null then raise exception 'NOT_FOUND'; end if; if p_action = 'decline' then update alliances set status = 'declined' where id = al.id; else if t.coins < v_cost or (select coins from teams where id = al.team_a) < v_cost then raise exception 'NOT_ENOUGH_COINS'; end if; update alliances set status = 'active', expires_at = now() + make_interval(mins => _cfg(t.event_id, 'alliance_minutes')) where id = al.id; perform _apply(al.team_a, 'alliance', 0, -v_cost, 0, 10, al.id::text, 'Alliance formed'); perform _apply(al.team_b, 'alliance', 0, -v_cost, 0, 10, al.id::text, 'Alliance formed'); perform _feed(t.arena_id, 'alliance.created', jsonb_build_object('a', (select number from teams where id = al.team_a), 'b', t.number)); end if; perform _ping_team(al.team_a, 'alliance'); elsif p_action = 'end' then select * into al from alliances where id = p_alliance and status = 'active' and (team_a = t.id or team_b = t.id) for update; if al.id is null then raise exception 'NOT_FOUND'; end if; update alliances set status = 'ended' where id = al.id; perform _ping_team(case when al.team_a = t.id then al.team_b else al.team_a end, 'alliance'); else raise exception 'BAD_REQUEST'; end if; perform _ping_team(t.id, 'alliance'); return jsonb_build_object('ok', true); end $$; create or replace function captain_bargain(p_token text, p_story uuid, p_accept boolean) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; s story_events; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into s from story_events where id = p_story and arena_id = t.arena_id and kind = 'bargain'; if s.id is null or (s.expires_at is not null and s.expires_at <= now()) then raise exception 'NOT_FOUND'; end if; if t.bargains @> jsonb_build_array(jsonb_build_object('id', s.id::text)) then raise exception 'ALREADY_ANSWERED'; end if; update teams set bargains = bargains || jsonb_build_array(jsonb_build_object('id', s.id::text, 'accept', p_accept)) where id = t.id; if p_accept then perform _apply(t.id, 'bargain', 0, coalesce((s.offer ->> 'coins')::int, 0), 0, coalesce((s.offer ->> 'trust')::int, 0), s.id::text, 'Accepted a Squad 00 bargain'); update arenas set threat = threat + coalesce((s.offer ->> 'threat')::int, 1) where id = t.arena_id; perform _ping_arena(t.arena_id, 'threat'); end if; perform _ping_team(t.id, 'bargain'); return jsonb_build_object('accepted', p_accept); end $$; create or replace function _auth_host(p_token text) returns uuid language plpgsql as $$ declare v uuid; begin select event_id into v from host_sessions where token_hash = _hash(p_token) and expires_at > now(); if v is null then raise exception 'HOST_AUTH'; end if; return v; end $$; create or replace function host_create_event(p_code text, p_name text, p_secret text, p_arenas int default 2) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_code text := upper(trim(p_code)); v_salt text := _new_token(); v_ev uuid; v_token text := _new_token(); i int; begin if v_code !~ '^[A-Z0-9]{3,12}$' then raise exception 'BAD_CODE'; end if; if p_secret is null or length(p_secret) < 6 then raise exception 'WEAK_SECRET'; end if; if p_arenas < 1 or p_arenas > 6 then raise exception 'BAD_ARENAS'; end if; if exists (select 1 from events where code = v_code) then raise exception 'CODE_TAKEN'; end if; insert into events(code, name, host_salt, host_secret_hash) values (v_code, coalesce(nullif(trim(p_name), ''), 'Hexa Battlegrounds'), v_salt, _hash(v_salt || p_secret)) returning id into v_ev; for i in 1..p_arenas loop insert into arenas(event_id, number, name) values (v_ev, i, 'Map ' || i); end loop; insert into host_sessions(token_hash, event_id) values (_hash(v_token), v_ev); insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'create_event', jsonb_build_object('code', v_code, 'arenas', p_arenas)); return jsonb_build_object('event_id', v_ev, 'token', v_token, 'code', v_code); end $$; create or replace function host_login(p_code text, p_secret text) returns jsonb language plpgsql security definer set search_path = public as $$ declare e events; v_token text := _new_token(); v_fails int; begin select * into e from events where code = upper(trim(p_code)); if e.id is null then raise exception 'HOST_AUTH'; end if; select count(*) into v_fails from audit_log where event_id = e.id and action = 'login_failed' and at > now() - interval '10 minutes'; if v_fails >= 10 then raise exception 'LOCKED_OUT'; end if; if e.host_secret_hash <> _hash(e.host_salt || coalesce(p_secret, '')) then insert into audit_log(event_id, actor, action, ok) values (e.id, 'anonymous', 'login_failed', false); return jsonb_build_object('error', 'HOST_AUTH'); end if; insert into host_sessions(token_hash, event_id) values (_hash(v_token), e.id); insert into audit_log(event_id, actor, action) values (e.id, 'host', 'login'); return jsonb_build_object('event_id', e.id, 'token', v_token, 'code', e.code); end $$; create or replace function host_generate_teams(p_token text, p_count int) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_start int; v_out jsonb := '[]'::jsonb; i int; v_pin text; v_salt text; v_arena uuid; v_size int; v_existing int; begin v_ev := _auth_host(p_token); if p_count < 1 or p_count > 120 then raise exception 'BAD_COUNT'; end if; v_size := _cfg(v_ev, 'arena_size'); select coalesce(max(number), 0) into v_start from teams where event_id = v_ev; for i in 1..p_count loop v_pin := lpad((floor(random() * 10000))::int::text, 4, '0'); v_salt := _new_token(); select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, v_start + i, 'Squad ' || (v_start + i), v_salt, _hash(v_salt || v_pin)); perform _add_item((select id from teams where event_id = v_ev and number = v_start + i), 'pistol', 1); perform _add_item((select id from teams where event_id = v_ev and number = v_start + i), 'medkit', 1); v_out := v_out || jsonb_build_object('number', v_start + i, 'pin', v_pin, 'map', (select number from arenas where id = v_arena)); end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'generate_teams', jsonb_build_object('count', p_count)); return v_out; end $$;
